import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Which customers a query asks for.
 *
 * <p>A customer matches when it satisfies both parts:
 * <ul>
 *   <li>the name text is split on whitespace, and every term must appear, ignoring
 *       case and accents, in the first name or the last name. An empty name matches
 *       everyone.</li>
 *   <li>with no statuses selected every status matches; otherwise the customer's
 *       status must be one of the selected ones.</li>
 * </ul>
 *
 * @param name     text typed into the name filter; blank means no name filter
 * @param statuses statuses to show; empty means every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICAL_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /**
     * Builds the predicate once so that the name terms are normalized once per
     * query rather than once per customer.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = nameTerms();
        return customer -> matchesName(customer, terms)
                && (statuses.isEmpty() || statuses.contains(customer.status()));
    }

    private List<String> nameTerms() {
        String trimmed = name.strip();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return Arrays.stream(WHITESPACE.split(trimmed))
                .map(CustomerFilter::fold)
                .toList();
    }

    private static boolean matchesName(Customer customer, List<String> terms) {
        if (terms.isEmpty()) {
            return true;
        }
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return DIACRITICAL_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
