+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+/**
+ * Drives the running application in a real, headless browser. Checks what
+ * Karibu cannot see: the address bar, the history, and how many queries typing
+ * costs the backend.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Test
+    void urlParametersFillTheFieldsAndTheSummary() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+        waitForVaadin();
+
+        assertEquals("vir", nameField().inputValue());
+        assertEquals("Showing 10 of 500", summary().textContent());
+    }
+
+    @Test
+    void typingNarrowsTheListAndUpdatesTheAddressBar() {
+        page.navigate(getUrl());
+        waitForVaadin();
+        int historyLength = historyLength();
+        queryLog.clear();
+
+        nameField().click();
+        page.keyboard().type("josephine", new Keyboard.TypeOptions().setDelay(80));
+        page.waitForFunction("() => window.location.search.includes('name=josephine')");
+        page.locator("span", new Page.LocatorOptions().setHasText("Showing 12 of 500")).waitFor();
+        waitForVaadin();
+
+        assertTrue(page.url().endsWith("?name=josephine"),
+                "The address bar should carry the name, was " + page.url());
+        assertEquals(historyLength, historyLength(), "Typing must not add history entries");
+
+        // One burst of typing should cost one or two queries, not one per keystroke.
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing a nine-letter name ran " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing a nine-letter name ran " + queryLog.pageQueries().size() + " page queries");
+    }
+
+    @Test
+    void clearingTheNameRemovesItFromTheAddressBar() {
+        page.navigate(getUrl() + "?name=vir");
+        waitForVaadin();
+
+        nameField().fill("");
+        waitForVaadin();
+        page.waitForFunction("() => !window.location.search.includes('name')");
+
+        assertFalse(page.url().contains("name="), "An empty name must leave no parameter, was " + page.url());
+        assertEquals("Showing 500 of 500", summary().textContent());
+    }
+
+    @Test
+    void statusSelectionIsWrittenToTheAddressBar() {
+        page.navigate(getUrl());
+        waitForVaadin();
+
+        Locator status = page.locator("vaadin-multi-select-combo-box");
+        status.click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED"))
+                .click();
+        page.keyboard().press("Escape");
+        waitForVaadin();
+        page.waitForFunction("() => window.location.search.includes('status=CLOSED')");
+
+        assertTrue(page.url().endsWith("?status=CLOSED"), "Was " + page.url());
+        assertEquals("Showing 166 of 500", summary().textContent());
+    }
+
+    private Locator nameField() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private Locator summary() {
+        return page.locator("span", new Page.LocatorOptions().setHasText("Showing"));
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+}
