+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer MAKINEN = new Customer(
+            2, "Dagny", "Mäkinen", "dagny@example.com", "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = new Customer(
+            3, "Joséphine", "Virtanen", "josephine@example.com", "France", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    @Test
+    void emptyFilterMatchesEveryone() {
+        assertTrue(matches(CustomerFilter.NONE, ADA));
+        assertTrue(matches(name("   "), MAKINEN));
+    }
+
+    @Test
+    void termsCanMatchEitherNameInAnyOrder() {
+        assertTrue(matches(name("ada aal"), ADA));
+        assertTrue(matches(name("aal   ada"), ADA));
+        assertTrue(matches(name("  ada  "), ADA));
+    }
+
+    @Test
+    void everyTermMustMatch() {
+        assertFalse(matches(name("ada virtanen"), ADA));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsInBothDirections() {
+        assertTrue(matches(name("makinen"), MAKINEN));
+        assertTrue(matches(name("MAKINEN"), MAKINEN));
+        assertTrue(matches(name("mäkinen"), MAKINEN));
+        assertTrue(matches(name("josephine"), JOSEPHINE));
+        assertTrue(matches(name("JOSÉPHINE"), JOSEPHINE));
+    }
+
+    @Test
+    void statusFilterRestrictsToSelectedStatuses() {
+        assertTrue(matches(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)), ADA));
+        assertFalse(matches(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)), MAKINEN));
+        assertTrue(matches(new CustomerFilter("", Set.of(CustomerStatus.PENDING, CustomerStatus.CLOSED)), MAKINEN));
+    }
+
+    @Test
+    void bothFiltersMustHold() {
+        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED));
+        assertFalse(matches(filter, ADA));
+    }
+}
